   review_codes=ARRAY['ERASURE_AUTH_PENDING'],next_review_at=coalesce(next_review_at,clock_timestamp()+interval '30 days')
   WHERE profile_id=p_profile_id RETURNING * INTO request;
  claimed:=true;
 END IF;
